import java.util.*;
class Solution {
    static int solve(String s) {
        Map<Character, Integer> last = new HashMap<>(); int start = 0; int best = 0;
        for (int i = 0; i < s.length(); i++) {
            if (last.containsKey(s.charAt(i)) && last.get(s.charAt(i)) >= start) start = last.get(s.charAt(i)) + 1;
            last.put(s.charAt(i), i); best = Math.max(best, i - start + 1);
        }
        return best;
    }
}
